    "Printed!\n\nPay ₹5 cash at the counter and collect your print.\nYour file has been deleted.\n\nNext time just send: Hello Print": "ಪ್ರಿಂಟ್ ಆಯಿತು!\n\nಕೌಂಟರ್‌ನಲ್ಲಿ ₹5 ನಗದು ಪಾವತಿಸಿ ನಿಮ್ಮ ಪ್ರಿಂಟ್ ತೆಗೆದುಕೊಳ್ಳಿ.\nನಿಮ್ಮ ಫೈಲ್ ಅಳಿಸಲಾಗಿದೆ.\n\nಮುಂದಿನ ಬಾರಿ ಇಷ್ಟೇ ಕಳುಹಿಸಿ: Hello Print",
    "Approximate Meta conversation charges. Your real bill depends on how many customers message you and what type of message it is.": "ಇವು ಅಂದಾಜು Meta ಸಂಭಾಷಣೆ ಶುಲ್ಕಗಳು. ನಿಮಗೆ ಎಷ್ಟು ಗ್ರಾಹಕರು ಸಂದೇಶ ಕಳುಹಿಸುತ್ತಾರೆ ಮತ್ತು ಯಾವ ಬಗೆಯ ಸಂದೇಶ ಎಂಬುದರ ಮೇಲೆ ನಿಮ್ಮ ನಿಜವಾದ ಬಿಲ್ ಅವಲಂಬಿತವಾಗಿರುತ್ತದೆ.",
    "Sharma Cyber Cafe — QR Se Print\n\nSend your file right here on WhatsApp.\nPDF · JPG · PNG\n\nAttachment → Document → file → Send\n\nB&W ₹5/page · Color ₹10/page": "ಶರ್ಮಾ ಸೈಬರ್ ಕೆಫೆ — QR Se Print\n\nನಿಮ್ಮ ಫೈಲ್ ಅನ್ನು ಇಲ್ಲಿಯೇ WhatsApp ನಲ್ಲಿ ಕಳುಹಿಸಿ.\nPDF · JPG · PNG\n\nಅಟ್ಯಾಚ್‌ಮೆಂಟ್ → ಡಾಕ್ಯುಮೆಂಟ್ → ಫೈಲ್ → ಕಳುಹಿಸಿ\n\nಕಪ್ಪು-ಬಿಳುಪು ₹5/ಪುಟ · ಬಣ್ಣ ₹10/ಪುಟ",
    "No app and no website for your customer. They scan your QR, WhatsApp opens with the message already typed, they send the file — and the print comes out at your counter.": "ನಿಮ್ಮ ಗ್ರಾಹಕರಿಗೆ ಆ್ಯಪ್ ಬೇಡ, ವೆಬ್‌ಸೈಟ್ ಬೇಡ. ಅವರು ನಿಮ್ಮ QR ಸ್ಕ್ಯಾನ್ ಮಾಡುತ್ತಾರೆ, ಸಂದೇಶ ಮೊದಲೇ ಟೈಪ್ ಆಗಿ WhatsApp ತೆರೆಯುತ್ತದೆ, ಅವರು ಫೈಲ್ ಕಳುಹಿಸುತ್ತಾರೆ — ಪ್ರಿಂಟ್ ನಿಮ್ಮ ಕೌಂಟರ್‌ನಲ್ಲಿ ಹೊರಬರುತ್ತದೆ."
