    "💰 Plans: ₹%s/month · ₹%s/year · ₹%s lifetime 👉 %s": "💰 ಪ್ಲಾನ್‌ಗಳು: ತಿಂಗಳಿಗೆ ₹%s · ವರ್ಷಕ್ಕೆ ₹%s · ಲೈಫ್‌ಟೈಮ್ ₹%s 👉 %s",
    "📅 Monthly — Starter features, renew every 30 days": "📅 ಮಾಸಿಕ — ಸ್ಟಾರ್ಟರ್ ಫೀಚರ್‌ಗಳು, ಪ್ರತಿ 30 ದಿನಕ್ಕೆ ರಿನ್ಯೂ",
