    "WhatsApp Se Print will not run if Virtualization is turned off in your computer's BIOS.": "ನಿಮ್ಮ ಕಂಪ್ಯೂಟರ್‌ನ BIOS ನಲ್ಲಿ Virtualization ಆಫ್ ಆಗಿದ್ದರೆ WhatsApp Se Print ಚಲಿಸುವುದಿಲ್ಲ.",
    "A QR code appears. On your phone: WhatsApp → Settings → Linked Devices → Link a Device → scan it.": "ಒಂದು QR code ಕಾಣುತ್ತದೆ. ನಿಮ್ಮ ಫೋನ್‌ನಲ್ಲಿ: WhatsApp → Settings → Linked Devices → Link a Device → ಅದನ್ನು ಸ್ಕ್ಯಾನ್ ಮಾಡಿ.",
    "A download link, plus your Serial Key and Shop ID. You can save them as a text file — keep it safe.": "ಡೌನ್‌ಲೋಡ್ ಲಿಂಕ್, ನಿಮ್ಮ Serial Key ಮತ್ತು Shop ID. ಅವನ್ನು text file ಆಗಿ ಸೇವ್ ಮಾಡಬಹುದು — ಸುರಕ್ಷಿತವಾಗಿ ಇಡಿ.",
    "Windows needs two features switched on. Download the file below and double-click it — it does everything for you. Say": "Windows ನಲ್ಲಿ ಎರಡು ಫೀಚರ್ ಆನ್ ಮಾಡಬೇಕು. ಕೆಳಗಿನ ಫೈಲ್ ಡೌನ್‌ಲೋಡ್ ಮಾಡಿ ಡಬಲ್-ಕ್ಲಿಕ್ ಮಾಡಿ — ಅದೇ ಎಲ್ಲವನ್ನೂ ಮಾಡುತ್ತದೆ. Windows ಅನುಮತಿ ಬಾಕ್ಸ್‌ನಲ್ಲಿ",
    "After that, if you want to continue, do not uninstall — the payment link is starting soon. You can then pay and get a Serial Key for one year.": "ಆ ನಂತರ ಮುಂದುವರಿಸಬೇಕಾದರೆ ಅನ್‌ಇನ್‌ಸ್ಟಾಲ್ ಮಾಡಬೇಡಿ — ಪೇಮೆಂಟ್ ಲಿಂಕ್ ಶೀಘ್ರದಲ್ಲೇ ಶುರುವಾಗುತ್ತದೆ. ಆಗ ಪಾವತಿಸಿ ಒಂದು ವರ್ಷಕ್ಕೆ ಸೀರಿಯಲ್ ಕೀ ಪಡೆಯಬಹುದು.",
    "🔒 Your customers' files are printed on your own computer only. Nothing is uploaded to any server, and every file is deleted automatically as soon as the print is done.": "🔒 ನಿಮ್ಮ ಗ್ರಾಹಕರ ಫೈಲ್‌ಗಳು ನಿಮ್ಮ ಸ್ವಂತ ಕಂಪ್ಯೂಟರ್‌ನಲ್ಲಿ ಮಾತ್ರ ಪ್ರಿಂಟ್ ಆಗುತ್ತವೆ. ಯಾವ server ಗೂ ಏನೂ ಅಪ್‌ಲೋಡ್ ಆಗುವುದಿಲ್ಲ, ಪ್ರಿಂಟ್ ಆದ ತಕ್ಷಣ ಪ್ರತಿ ಫೈಲ್ ತಾನಾಗಿಯೇ ಡಿಲೀಟ್ ಆಗುತ್ತದೆ.",
    "Testing Demo is for 2 days. After that, if you want to continue, do not uninstall — the payment link is starting soon. You can then pay and get a Serial Key for one year.": "ಟೆಸ್ಟಿಂಗ್ ಡೆಮೋ 2 ದಿನಗಳಿಗೆ. ಆ ನಂತರ ಮುಂದುವರಿಸಬೇಕಾದರೆ ಅನ್‌ಇನ್‌ಸ್ಟಾಲ್ ಮಾಡಬೇಡಿ — ಪೇಮೆಂಟ್ ಲಿಂಕ್ ಶೀಘ್ರದಲ್ಲೇ ಶುರುವಾಗುತ್ತದೆ. ಆಗ ಪಾವತಿಸಿ ಒಂದು ವರ್ಷಕ್ಕೆ ಸೀರಿಯಲ್ ಕೀ ಪಡೆಯಬಹುದು."
