    "Sunday raat 11:59 ke baad 0 se shuru": "ಭಾನುವಾರ ರಾತ್ರಿ 11:59 ನಂತರ 0 ಯಿಂದ ಆರಂಭ",
    "⏳ Print hote hi file delete ho jaayegi — warna raat 11:59 baje khud": "⏳ ಪ್ರಿಂಟ್ ಆದ ತಕ್ಷಣ ಫೈಲ್ ಅಳಿಸಲ್ಪಡುತ್ತದೆ — ಇಲ್ಲದಿದ್ದರೆ ರಾತ್ರಿ 11:59ಕ್ಕೆ ತಾನಾಗಿಯೇ",
    "%d din me ✅": "%d ದಿನಗಳಲ್ಲಿ ✅",
    "Free demo se shuru karo. Phir Rs %d/month ka monthly plan, Rs %d/%d/%d ke yearly plan (Starter/Pro/Premium), ya Rs %d one-time lifetime plan — ek baar do, hamesha chalao. Koi hidden charge nahi, koi per-print commission nahi.": "ಉಚಿತ ಡೆಮೋದಿಂದ ಆರಂಭಿಸಿ. ನಂತರ ತಿಂಗಳಿಗೆ ರೂ.%d ಮಾಸಿಕ ಪ್ಲಾನ್, ರೂ.%d/%d/%d ವಾರ್ಷಿಕ ಪ್ಲಾನ್‌ಗಳು (ಸ್ಟಾರ್ಟರ್/ಪ್ರೊ/ಪ್ರೀಮಿಯಂ), ಅಥವಾ ರೂ.%d ಒಮ್ಮೆ ಪಾವತಿಸುವ ಲೈಫ್‌ಟೈಮ್ ಪ್ಲಾನ್ — ಒಮ್ಮೆ ಕೊಡಿ, ಶಾಶ್ವತವಾಗಿ ನಡೆಸಿ. ಗುಪ್ತ ಶುಲ್ಕ ಇಲ್ಲ, ಪ್ರಿಂಟ್‌ಗೆ ಕಮಿಷನ್ ಇಲ್ಲ.",
    "There is a free demo first. After that plans start at ₹%d per month; yearly plans are ₹%d (Starter), ₹%d (Pro) and ₹%d (Premium); and there is a ₹%d one-time Lifetime plan. There is no per-print commission and no hidden charge.": "ಮೊದಲು ಉಚಿತ ಡೆಮೋ ಇದೆ. ನಂತರ ಪ್ಲಾನ್‌ಗಳು ತಿಂಗಳಿಗೆ ₹%d ರಿಂದ ಆರಂಭ; ವಾರ್ಷಿಕ ಪ್ಲಾನ್‌ಗಳು ₹%d (ಸ್ಟಾರ್ಟರ್), ₹%d (ಪ್ರೊ) ಮತ್ತು ₹%d (ಪ್ರೀಮಿಯಂ); ಜೊತೆಗೆ ₹%d ಒಮ್ಮೆ ಪಾವತಿಸುವ ಲೈಫ್‌ಟೈಮ್ ಪ್ಲಾನ್ ಇದೆ. ಪ್ರಿಂಟ್‌ಗೆ ಕಮಿಷನ್ ಇಲ್ಲ, ಗುಪ್ತ ಶುಲ್ಕ ಇಲ್ಲ.",
    "₹%d — EK baar": "₹%d — ಒಂದೇ ಬಾರಿ",
    "Free demo se shuru karo. Phir Rs %d/month ka monthly plan, Rs %d ka yearly plan, ya Rs %d one-time lifetime plan — ek baar do, hamesha chalao. Koi hidden charge nahi, koi per-print commission nahi.": "ಉಚಿತ ಡೆಮೋದಿಂದ ಆರಂಭಿಸಿ. ನಂತರ ತಿಂಗಳಿಗೆ ರೂ.%d ಮಾಸಿಕ ಪ್ಲಾನ್, ರೂ.%d ವಾರ್ಷಿಕ ಪ್ಲಾನ್, ಅಥವಾ ರೂ.%d ಒಮ್ಮೆ ಪಾವತಿಸುವ ಲೈಫ್‌ಟೈಮ್ ಪ್ಲಾನ್ — ಒಮ್ಮೆ ಕೊಡಿ, ಶಾಶ್ವತವಾಗಿ ನಡೆಸಿ. ಗುಪ್ತ ಶುಲ್ಕ ಇಲ್ಲ, ಪ್ರಿಂಟ್‌ಗೆ ಕಮಿಷನ್ ಇಲ್ಲ.",
    "There is a free demo first. After that plans start at ₹%d per month; the yearly plan is ₹%d; and there is a ₹%d one-time Lifetime plan. There is no per-print commission and no hidden charge.": "ಮೊದಲು ಉಚಿತ ಡೆಮೋ ಇದೆ. ನಂತರ ಪ್ಲಾನ್‌ಗಳು ತಿಂಗಳಿಗೆ ₹%d ರಿಂದ ಆರಂಭ; ವಾರ್ಷಿಕ ಪ್ಲಾನ್ ₹%d; ಜೊತೆಗೆ ₹%d ಒಮ್ಮೆ ಪಾವತಿಸುವ ಲೈಫ್‌ಟೈಮ್ ಪ್ಲಾನ್ ಇದೆ. ಪ್ರಿಂಟ್‌ಗೆ ಕಮಿಷನ್ ಇಲ್ಲ, ಗುಪ್ತ ಶುಲ್ಕ ಇಲ್ಲ.",
    "WhatsApp me aapka personal number public ho jata hai, chat me files kho jaati hain, aur hisaab manually rakhna padta hai. QR Se Print me number private rehta hai, har print ka payment record automatic banta hai, aur customer ki file print hote hi khud delete ho jaati hai.": "WhatsApp ನಲ್ಲಿ ನಿಮ್ಮ ವೈಯಕ್ತಿಕ ಸಂಖ್ಯೆ ಎಲ್ಲರಿಗೂ ಗೊತ್ತಾಗುತ್ತದೆ, ಚಾಟ್‌ನಲ್ಲಿ ಫೈಲ್‌ಗಳು ಕಳೆದುಹೋಗುತ್ತವೆ, ಲೆಕ್ಕವನ್ನೂ ಕೈಯಾರೆ ಇಡಬೇಕು. QR Se Print ನಲ್ಲಿ ನಿಮ್ಮ ಸಂಖ್ಯೆ ಖಾಸಗಿಯಾಗಿಯೇ ಇರುತ್ತದೆ, ಪ್ರತಿ ಪ್ರಿಂಟ್‌ಗೂ ಪಾವತಿ ದಾಖಲೆ ತಾನಾಗಿಯೇ ಆಗುತ್ತದೆ, ಮತ್ತು ಗ್ರಾಹಕರ ಫೈಲ್ ಪ್ರಿಂಟ್ ಆದ ತಕ್ಷಣ ತಾನೇ ಅಳಿಸಿಹೋಗುತ್ತದೆ."
